create table public.bank_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
insert into public.bank_settings (key, value) values ('free_year_count', '2'), ('min_questions_for_listing', '10'), ('min_questions_for_practice', '5'), ('qualify_ratio', '0.9');
create table public.exam_profiles (id uuid primary key default gen_random_uuid(), exam_slug text not null unique, display_name text not null, subjects_required int not null default 1, compulsory_subject_slug text, shared_timer boolean not null default false, total_minutes int, default_question_count int not null, default_minutes int not null, min_questions int not null default 5, max_questions int not null default 100, min_minutes int not null default 5, max_minutes int not null default 240, verified boolean not null default false, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.exam_profile_subjects (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.exam_profiles(id) on delete cascade, subject_slug text not null, question_count int not null, minutes int, unique (profile_id, subject_slug));
insert into public.exam_profiles (exam_slug, display_name, subjects_required, compulsory_subject_slug, shared_timer, total_minutes, default_question_count, default_minutes, notes) values ('jamb','JAMB UTME',4,'english-language',true,120,40,120,'4 subjects, 180 questions, 2 hours, English 60 and others 40.'), ('waec','WAEC WASSCE (objective papers)',1,null,false,null,50,60,'Objective papers only. English objective is 80 questions in 1 hour.'), ('neco','NECO SSCE (objective papers)',1,null,false,null,60,60,'Only English is confirmed (80 questions, 50 minutes, 2026). Other subjects use an unverified default of 60 questions in 60 minutes.'), ('post-utme','Post-UTME',4,'english-language',true,60,20,60,'Varies by university. Generic default only.');
insert into public.exam_profile_subjects (profile_id, subject_slug, question_count, minutes) select id,'english-language',60,null from public.exam_profiles where exam_slug='jamb';
insert into public.exam_profile_subjects (profile_id, subject_slug, question_count, minutes) select id,'english-language',80,60 from public.exam_profiles where exam_slug='waec';
insert into public.exam_profile_subjects (profile_id, subject_slug, question_count, minutes) select id,'english-language',80,50 from public.exam_profiles where exam_slug='neco';
alter table public.bank_settings enable row level security;
alter table public.exam_profiles enable row level security;
alter table public.exam_profile_subjects enable row level security;
create or replace view public.v_catalog with (security_invoker = true) as select e.slug as exam_slug, q.exam_year, s.slug as subject_slug, s.name as subject_name, count(*) filter (where q.status='published') as published_count, count(*) filter (where q.status='published' and q.has_passage) as passage_count, count(*) filter (where q.status='published' and q.image_url is not null) as image_count from public.questions q join public.exams e on e.id=q.exam_id join public.subjects s on s.id=q.subject_id group by e.slug,q.exam_year,s.slug,s.name;
revoke all on public.bank_settings, public.exam_profiles, public.exam_profile_subjects, public.v_catalog from anon, authenticated;
